  async applications(cid:string,query:Record<string,unknown>,actor:EntityActor):Promise<any>{portalObject(query,['workspaceId','size','cursor','state','search']);const scope=await this.adminReadScope(cid,query,actor,'applications'),ws={id:scope.wid},version=scope.version;const size=pageSize(query.size),search=portalText(query.search??'',128,false),binding=this.secrets.fingerprint({cid,wid:ws.id,actor:actor.user.id,version,size,search,state:query.state??null}),offset=this.cursors.decode(query.cursor,binding)?.offset??0;const rows=await this.db.query<any>(`SELECT id,name,description,status,revision,created_at,developer_id FROM portal_applications WHERE cluster_id=$1 AND workspace_id=$2 AND ($3::text IS NULL OR status=$3) AND ($4='' OR name ILIKE '%'||$4||'%') ORDER BY created_at DESC,id DESC LIMIT $5 OFFSET $6`,[cid,ws.id,query.state==='archived'?'deleted':query.state??null,search,size,offset]);await this.adminReadFinal({cid,wid:ws.id,version},actor,['applications']);return{items:rows.map(row=>({id:row.id,name:row.name,description:row.description,state:row.status==='deleted'?'archived':row.status,revision:row.revision,createdAt:new Date(row.created_at).toISOString(),developerId:row.developer_id})),size,total:null,nextCursor:rows.length===size?this.cursors.encode(binding,{offset:offset+size}):null};}
